insert into public.products (slug, name, brand_id, category, gender, concentration, scent_families, description, brand_story, top_notes, heart_notes, base_notes, longevity, sillage, rating, review_count, is_new, is_bestseller, is_featured, is_on_sale, original_price, tags, images) values ('nocturne-noir-eau-de-parfum', 'Nocturne Noir', (select id from public.brands where name = 'Maison Noir' limit 1), 'men'::product_category, 'men'::gender_t, 'EDP'::concentration, ARRAY['oriental','woody','spicy'], 'A brooding evening scent built around black amber, smoked oud, and bitter cocoa. Wears close to the skin, then announces itself after the first hour.', 'Born in a Parisian atelier in 1923, Maison Noir built its reputation on compositions that refuse to be polite. Nocturne Noir is the house''s signature — a love letter to the city after midnight.', ARRAY['Bergamot','Black Pepper','Cardamom'], ARRAY['Iris','Bulgarian Rose','Smoked Tea'], ARRAY['Black Amber','Oud','Bitter Cocoa','Vetiver'], 'Long-lasting'::longevity_t, 'Strong'::sillage_t, 4.8, 412, false, true, true, false, NULL, '{}', ARRAY['/products/0.jpg','/products/4.jpg','/products/8.jpg']);
