insert into public.product_reviews (product_id, user_name, avatar, rating, review_date, title, body, photos, verified, helpful, unhelpful) values ((select id from public.products where slug = 'nocturne-noir-eau-de-parfum' limit 1), 'Marcus J.', 'M', 5, '2026-06-12'::date, 'My signature scent', 'I get compliments every time I wear this. Lasts 8+ hours on my skin and the drydown is incredible. Smells like a high-end gentleman''s club.', '{}', true, 87, 4);
insert into public.product_reviews (product_id, user_name, avatar, rating, review_date, title, body, photos, verified, helpful, unhelpful) values ((select id from public.products where slug = 'nocturne-noir-eau-de-parfum' limit 1), 'Ahmed K.', 'A', 5, '2026-05-30'::date, 'Sophisticated and unique', 'Not your typical designer scent. The oud is present but not overpowering. Perfect for evening events and cold weather.', ARRAY['/products/9.jpg'], true, 56, 2);
insert into public.product_reviews (product_id, user_name, avatar, rating, review_date, title, body, photos, verified, helpful, unhelpful) values ((select id from public.products where slug = 'nocturne-noir-eau-de-parfum' limit 1), 'Elena R.', 'E', 4, '2026-04-18'::date, 'Bought for my husband', 'He loves it. A bit heavy for summer but absolutely perfect for fall/winter evenings.', '{}', true, 23, 1);
insert into public.product_qa (product_id, user_name, question, answer, answered_by, qa_date) values ((select id from public.products where slug = 'nocturne-noir-eau-de-parfum' limit 1), 'Sam T.', 'How does this compare to Tom Ford Oud Wood?', 'Nocturne Noir is significantly smokier and more resinous, with a real oud note vs. the synthetic oud in Oud Wood. They''re both excellent but serve different moods.', 'Perfumeria Concierge', '2026-07-02'::date);
insert into public.product_qa (product_id, user_name, question, answer, answered_by, qa_date) values ((select id from public.products where slug = 'nocturne-noir-eau-de-parfum' limit 1), 'Priya N.', 'Is this suitable for daytime office wear?', 'It''s a little intense for a tight office environment. We recommend 1-2 sprays max, applied to chest rather than neck.', 'Perfumeria Concierge', '2026-06-28'::date);
insert into public.products (slug, name, brand_id, category, gender, concentration, scent_families, description, brand_story, top_notes, heart_notes, base_notes, longevity, sillage, rating, review_count, is_new, is_bestseller, is_featured, is_on_sale, original_price, tags, images) values ('cedar-smoke', 'Cedar Smoke', (select id from public.brands where name = 'Noir Cedar' limit 1), 'men'::product_category, 'men'::gender_t, 'EDT'::concentration, ARRAY['woody','leather','smoky'], 'Smoldering Atlas cedar, charred birch, and a whisper of leather. The cabin-in-the-woods fantasy, bottled.', 'Noir Cedar has been sourcing the finest cedarwood from Atlas Mountains since 1978. Cedar Smoke is our most loved release — a love letter to the great outdoors.', ARRAY['Pink Pepper','Juniper','Lemon Zest'], ARRAY['Atlas Cedar','Cypress','Geranium'], ARRAY['Charred Birch','Leather','Sandalwood','Tonka'], 'Long-lasting'::longevity_t, 'Moderate'::sillage_t, 4.6, 287, true, false, false, false, NULL, '{}', ARRAY['/products/1.jpg','/products/5.jpg']);
