insert into public.product_qa (product_id, user_name, question, answer, answered_by, qa_date) values ((select id from public.products where slug = 'rosa-velvet-eau-de-parfum' limit 1), 'Hannah L.', 'Is this a heavy fragrance?', 'No, it''s surprisingly fresh and modern. The rose is balanced with bright top notes, so it never feels old-fashioned.', 'Perfumeria Concierge', '2026-07-01'::date);
